#include <unity.h>
#include "core/speedbike_protocol.h"
void test_frames(){FrameDecoder d;DecodedFrame f{};const uint8_t a[]={0,0x54,0x46,0x52};const uint8_t b[]={0x58,1,1,0xba};d.push(a,sizeof a);TEST_ASSERT_FALSE(d.next(f));d.push(b,sizeof b);TEST_ASSERT_TRUE(d.next(f));TEST_ASSERT_EQUAL_HEX8(0x52,f.op);const uint8_t bad[]={0x54,0x46,0x41,0x5a,1,1,0};d.push(bad,sizeof bad);TEST_ASSERT_FALSE(d.next(f));} void test_builders(){uint8_t o[16]{};TEST_ASSERT_EQUAL_UINT(7,buildSessionNotice(o,sizeof o));TEST_ASSERT_EQUAL_HEX8(0xac,o[6]);TEST_ASSERT_EQUAL_UINT(13,buildPasswordFrame(o,sizeof o));TEST_ASSERT_EQUAL_HEX8(0x9f,o[12]);} int main(int,char**){UNITY_BEGIN();RUN_TEST(test_frames);RUN_TEST(test_builders);return UNITY_END();}
